import 'package:cloud_firestore/cloud_firestore.dart';import 'package:flutter/material.dart';class CategoriesAdminPage extends StatelessWidget{const CategoriesAdminPage({super.key});@override Widget build(BuildContext c){final t=TextEditingController();return Scaffold(appBar:AppBar(title:const Text('Kategori Marketplace')),floatingActionButton:FloatingActionButton(onPressed:()=>showDialog(context:c,builder:(d)=>AlertDialog(title:const Text('Kategori baru'),content:TextField(controller:t),actions:[TextButton(onPressed:()=>Navigator.pop(d),child:const Text('Batal')),FilledButton(onPressed:()async{if(t.text.trim().isNotEmpty)await FirebaseFirestore.instance.collection('categories').add({'name':t.text.trim(),'active':true,'createdAt':FieldValue.serverTimestamp()});if(d.mounted)Navigator.pop(d);},child:const Text('Simpan'))])),child:const Icon(Icons.add)),body:StreamBuilder<QuerySnapshot<Map<String,dynamic>>>(stream:FirebaseFirestore.instance.collection('categories').snapshots(),builder:(c,s){if(!s.hasData)return const Center(child:CircularProgressIndicator());return ListView(children:s.data!.docs.map((d)=>ListTile(title:Text(d.data()['name']??''),trailing:Switch(value:d.data()['active']??true,onChanged:(v)=>d.reference.update({'active':v})))).toList());}));}}